(33, 1, '2025-07-14 13:39:49', '2025-07-14 13:39:49', 'Pendidikan dan pengajaran di dalam Republik Indonesia harus berdasarkan kebudayaan dan kemasyarakatan bangsa Indonesia, menuju ke arah kebahagiaan batin serta keselamatan hidup lahir.', 'Konsep Otomatis', '', 'publish', 'closed', 'closed', '', 'konsep-otomatis', '', '', '2025-07-14 13:40:29', '2025-07-14 13:40:29', '', 0, 'http://localhost/smpm2pagelaran/?post_type=quotes&#038;p=33', 0, 'quotes', '', 0),
(34, 1, '2025-07-14 13:40:13', '2025-07-14 13:40:13', 'Dengan adanya budi pekerti, tiap-tiap manusia berdiri sebagai manusia merdeka (berpribadi), yang dapat memerintah atau menguasai diri sendiri.', 'Konsep Otomatis', '', 'publish', 'closed', 'closed', '', 'konsep-otomatis-2', '', '', '2025-07-14 13:40:13', '2025-07-14 13:40:13', '', 0, 'http://localhost/smpm2pagelaran/?post_type=quotes&#038;p=34', 0, 'quotes', '', 0),
